DATE='2026-10-16'
source_rows=[
('ch19_lsa','勞動基準法：勞動契約、工資、工時與離職權益','https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=N0030001','法律','第2、9、9-1、10-1、11至19、22-1、23至26、30、32-1、38至40、63-1及84-1條；本批以各條審閱紀錄列明的主張為準。修正日期2024-07-31，不把全部勞務提供者直接視為本法勞工。'),
('ch19_lsa_rules','勞動基準法施行細則：年資、競業補償與特休工資','https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=N0030002','法規命令','第5、7、7-1至7-3、24及24-1條；年資、競業合理補償、特休年度與一日工資規則。'),
('pension','勞工退休金條例','https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=N0030020','法律','本批核對第11、12及14條：新舊年資區分、新制資遣費及30日給付期限、雇主提繳原則；其他引用仍需逐條審閱。'),
('probation','勞動部：試用期之約定','https://www.mol.gov.tw/1607/28162/28296/28340/28342/28356/47085/','主管機關說明','試用期間合理約定；勞動權益不因試用而排除，終止仍須法定事由並按事由處理預告及資遣。'),
('noticepay','勞動部：預告期間及預告工資之計算','https://www.mol.gov.tw/1607/28162/28296/28340/28342/28348/47070/','主管機關說明','預告期間從通知次日起按曆日計算；預告工資按應補足日數及一日工資計算；計月者最近一個月正常工作工資除以30，低於日平均工資時採較高者。'),
('laborcalc','勞動部：月薪制加班費試算系統與前置條件','https://calcr2.mol.gov.tw/Monthly','官方試算說明','試算預設週一至五每日8小時、週六休息日與週日例假；部分工時、輪班及彈性工時不一定符合，不直接當成個案核定。'),
('contractwork','勞動部：勞動契約如何認定','https://www.mol.gov.tw/1607/28162/28296/28340/28342/28344/','主管機關說明','依個案事實及整體從屬性判斷，不受承攬、委任等契約名稱拘束。'),
('labordispute','勞動部：勞資爭議調解制度與申請方式','https://www.mol.gov.tw/1607/28162/28296/28410/28412/','主管機關服務說明','地方政府調解為免費訴訟外程序；由任一方向勞務提供地地方政府申請，須敘明當事人及請求事项，代理出席須委託書。'),
('unemployment','就業保險法：離職事由爭議與離職證明','https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=N0050021','法律','本批核對第11、23及25條：資格並非僅看文件名稱；離職原因爭議仍可依法申請，文件取得困難時須經公立就服機構同意以書面釋明代替。'),
('wage2026','勞動部：按件計薪勞工權益與115年最低工資','https://www.mol.gov.tw/1607/28162/28166/28180/28182/28188/30519/','主管機關說明','自2026-01-01起月最低工資新臺幣29,500元、時最低工資196元；按件且按月或按日結算的比較方式有別，並非以最低時薪換算所有月薪工資。'),
('laboraid','勞動部：勞工法律及生活費用扶助','https://www.mol.gov.tw/1607/28752/28774/28776/28778/30712/','主管機關方案說明','勞動事件代理、必要費用與必要生活費分項申請，各有案件及資力等條件；不是所有勞工或所有程序自動免費。'),
('ch19_labor_events','勞動事件法：調解、證據與暫時權利保護','https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=B0010064','法律','第16、35、38、49及50條；確認僱傭及調職爭議的暫時處分须由法院按要件裁定，並非申請即獲准；出勤紀錄有推定與反證空間。'),
('ch19_trade_secret','營業秘密法：秘密要件與侵害責任','https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=J0080028','法律','第2、10及13-1條；營業秘密有法定要件，不因檔名機密即當然成立；非授權擅自取得、重製、使用或洩漏可能涉及責任。'),
('ch19_service','勞動部：服務證明書','https://www.mol.gov.tw/1607/28162/28296/81778/81796/81939/post','主管機關說明','服務證明用於證明工作經歷，不應記載不利求職事項；與失業給付所需離職原因證明不同。')]
S=[]
for key,title,url,kind,support in source_rows:
 support=support.replace('事项','事項').replace('须','須')
 S.append(dict(id=key,title=title,url=url,published_at=None,accessed_at=DATE,supports=support,evidence_type=kind,scope_note='本條目所列法律或官方說明，逐項核對範圍見review；編者操作建議不冒充法定義務。'))
E=[]
def entry(n,title,scope,action,benefit,risk,refs,claims,change):
 E.append(dict(id=f'TW-19-{n:03}',title=title,sections=[scope,action,benefit,risk],source_ids=refs,source_claims=claims,localization_changes=change,limits='僅適用本文列明的臺灣法規與身分条件；個案事實、工時制度、終止事由及約定仍須確認。來源核對為AI輔助編修，不是律師個案意見。'.replace('条件','條件')))
entry(1,'加班費按工作日類型與實際工時核對，不套用外國倍率',
'先確認屬適用勞基法的勞工，並辨識當天是正常工作日、休息日、例假、國定假日或特休。星期六不一定是休息日，星期日也不一定是例假；輪班及合法變形工時要另外核對。平日延長工時前2小時，按平日每小時工資額加給至少三分之一，再延長2小時加給至少三分之二，並非所有加班統一乘1.5、2或3。',
'先整理班表、出勤至分鐘的紀錄、加班指示與薪資明細，再按第24、39及40條分開計算。每月正常工資、延長工時工資及既付金額要分欄，不用最低時薪直接取代每個人的平日時薪。補休須在加班事實發生後由勞工選擇並經雇主同意，以實際加班時數換補休；到期或契約終止仍未休的部分，按加班當日工資計算標準補發，不能逕用一比一工資抵掉加成。',
'可先使用勞動部免費試算，但須先讀其週一至五每日8小時等假設；不符合時向工作地勞工局處提出資料請協助。法定出勤紀錄雇主須保存5年，勞工請求自己的副本不得拒絕。IT、主管或業務的職稱不等於免加班費；第84條之1另須公告適用、書面約定及主管機關核備。',
'自行整理主要成本是時間與少量備份空間；地方調解免費，法院及律師費另計。工時是否成立仍須看受指揮工作的實際情況，不能只用通訊軟體最後上線時間當成全部加班。行政罰鍰不是付給勞工的加班費，也沒有一律加付50%至100%的臺灣通則。',
['ch19_lsa','laborcalc','labordispute'],{'ch19_lsa':'第24、30、32-1、36、39、40及84-1條：工資加成、補休結清、出勤副本及責任制要件。','laborcalc':'網頁前置條件明示班表假設、部分工時及輪班誤差。','labordispute':'調解免費且由勞務提供地地方政府受理。'},'移除中國加班倍率及監察加付比例，避免補休等於放棄加班費。')
entry(2,'特休依適用年資取得，滿10年為16日而非仍維持15日',
'適用勞基法者在同一雇主或事業單位繼續工作：滿6個月未滿1年有3日；滿1年未滿2年7日；滿2年未滿3年10日；滿3年未滿5年每年14日；滿5年未滿10年每年15日。滿10年為16日，之後每滿1年再加1日，最多30日；不能把「10年以上」誤解成第11年才第一次增加。',
'依到職日與依法可併計年資確認資格，再確認雙方採週年、曆年或其他依法協議年度。特休日原則由勞工排定，雇主有經營急迫需求時應協商調整，不是任意拒絕。年度結束或契約終止未休畢者依法給工資；年度末遞延至下一年度須双方協商，遞延後到期或終止仍未休也要結清。'.replace('双方','雙方'),
'將各年度取得、已休、協議遞延及應結清日數與薪資明細對帳。未休工資依施行細則第24-1條，以未休日數乘依法計算的一日工資；月薪制以年度終結或終止前最近一個月正常工作時間工資除以30等規則處理，不是把未休部分一律換成三倍工資。',
'保存自己的請假申請、公司回覆與結算明細即可，不需購買特休代辦。部分工時、留職停薪、企業轉讓年資承認等情況另核對，不把不同雇主年資全部相加。較優約定可保留；日期結算方式不能把法定最低日數偷偷減少。發生爭議時先請雇主書面說明計算基礎。',
['ch19_lsa','ch19_lsa_rules'],{'ch19_lsa':'第10、20、38及39條：年資併計與承認、特休各門檻、排休及未休結清。','ch19_lsa_rules':'第5、24及24-1條：年資及年度選擇、一日工資計算。'},'補正10年16日門檻，移除外國未休三倍算法。')
entry(3,'試用期不是勞動保障空窗，也不是雇主可任意解僱的期間',
'依勞動部試用期說明，勞雇得按工作特性、誠信原則合理約定試用期間；相關勞動權益並不因試用而消失。臺灣没有通用的「試用薪資只能拿80%」或所有職務一律最長幾個月的規定。'.replace('没有','沒有'),
'到職前寫明薪資、工作、試用期間、評估標準與期滿處理，並保留到職日。要求公司確認依法適用的加保及勞退提繳安排，不接受「通過試用才算到職」；各保險納保資格仍需按人員與單位身分分別判斷。若要延長試用或改薪，先索取新條件與理由，不因口頭通知就以為原約定已失效。',
'截至查核日，2026年一般最低工資為每月新臺幣29,500元、每小時196元，自2026-01-01實施，適用時要分清月薪、時薪及工時制度。下一年度如有公告不能提前當成本年度標準；這裡也不是替所有職類試算實領薪資。年資從受僱日起算，不能任意排除試用月份。',
'自留契約及評估資料成本低，能降低事後對薪資與年資的爭議。試用不適任而終止仍須核對勞基法第11、12或13條但書等合法事由；依第11條資遣時另確認預告與資遣費，不是試用就一律沒有。未滿3個月不代表可以無合法理由解僱；具體事由爭執可向勞工局處求助。',
['probation','wage2026','ch19_lsa','ch19_lsa_rules','pension'],{'probation':'主管機關明示合理試用約定、權益同一般勞工及終止事由限制。','wage2026':'官方頁載明2026-01-01生效之月29,500元、時196元與計薪方式。','ch19_lsa':'第11至17條及最低勞動條件規範；無試用豁免。','ch19_lsa_rules':'第5條明定工作年資自受僱當日起算，不能任意扣除試用期間。','pension':'第7、12及14條適用身分、資遣與雇主提繳原則。'},'刪除80%薪資及試用任意解僱說法，區分合理約定與法定最低保障。')
entry(4,'資遣費拆分新舊年資，以平均工資而非只用本薪計算',
'先確認離職事由確實有資遣費請求基礎，不是任何離職都有。適用勞退新制的年資，依條例第12條，每滿1年給半個月平均工資，未滿1年按比例，最高6個月。舊制年資原則按勞基法第17條每滿1年給1個月平均工資，剩餘月數依法比例計算，未滿1個月以1個月計；混合年資不可全部套同一制。',
'列出到職、選制、契約終止及依法影響年資的日期，整理計算事由前6個月工資與應排除期間，再核對平均工資。工資須看勞務對價及實際給付性質，不只看「本薪」名稱，也不直接拿投保薪資級距替代。工資期間不足6個月、按時日件計酬與特殊排除期間，另依法律及細則計算。',
'將資遣費、預告不足工資、最後薪資與未休特休工資分成四項，請公司出具明細及付款日。資遣費應於終止勞動契約後30日內發給。純算式示例：若依法確認全為新制2年6個月、月平均工資新臺幣40,000元，資遣費為40,000×0.5×2.5＝50,000元；這是假設案例，不代表你的年資或平均工資已認定。',
'先自行整理並用官方資訊核對，不必預付代辦才能請領。平均工資、終止事由及年資有爭議時，地方調解免費，訴訟費用另計。資遣費不是勞退個人專戶提領，不能由雇主叫勞工自己領退休金來抵，也不能用一筆未列清用途的款項讓你誤以為所有權益已結清。',
['pension','ch19_lsa','ch19_lsa_rules','labordispute'],{'pension':'第11、12條保留舊年資、新制半年基数及30日給付期限。'.replace('基数','基數'),'ch19_lsa':'第2條工資與平均工資，第17、18條舊制資遣及不得請領情形。','ch19_lsa_rules':'第2條平均工資排除期間與第5條年資；不能只看固定本薪。','labordispute':'地方調解為免費且不同於法院程序。'},'移除單用月薪乘年資及所有離職都能領資遣費的簡化。')
entry(5,'預告工資補不足的曆日數，不是一律再給一個月',
'雇主依勞基法第11條或第13條但書終止契約時，繼續工作滿3個月未滿1年預告10日；滿1年未滿3年20日；滿3年30日。未依法預告的部分須給預告期間工資。不同終止事由有不同規則，依法成立的第12條終止並非同一套預告；不能一概套用外國N+1。',
'保存明確通知及最後工作日，依勞動部109年令釋，以通知次日起按曆日計至依約提供勞務的最後一日，包含假日。只補不足日數，不把已完整預告的日數再算一次。月薪者一日工資以契約終止前最近一個月正常工作時間所得工資除以30；若低於依法算得日平均工資，改採較高的日平均工資。',
'例：依法應預告20日卻當日終止，最近一個月正常工資30,000元、依法算得日平均工資1,100元時，用20×1,100＝22,000元，不是20×1,000元。這是條件式示例；另有部分預告、停止出勤但契約未終止等情況先確認日期。受資遣預告後，為另謀工作每星期可請不超過2日工作時間的有薪謀職假。',
'核對通知及薪資的成本主要是時間；請公司把通知日期、契約終止日與工資算法寫清楚。單看未滿3個月沒有第16條法定預告天數，不代表沒有其他約定或可任意解僱。薪資代通知也不能讓原本欠缺合法事由的解僱自動合法。拿不準時先諮詢勞工局處，避免誤把最後出勤日當成退保或契約終止日。',
['ch19_lsa','noticepay'],{'ch19_lsa':'第16條10／20／30日門檻、每週2日工作時間謀職假、第18條例外。','noticepay':'109年令釋的次日起按曆日計算、一日工資及採較高日平均工資；官方例算20×1,100元。'},'改為依法定事由、預告差額與一日工資計算，不給通用N+1保證。')
entry(6,'爭執解僱先保留異議與工作意願，調解與暫時處分分開處理',
'認為解僱欠缺合法事由時，先釐清你要主張僱傭關係仍存在，還是要協議終止並請求款項。臺灣不是違法解僱一律領2倍資遣費；解僱效力、工資、資遣費與損害賠償有不同要件，也可能存在不能同時成立的請求。',
'保存公司通知、原契約、考核與往來，以可留證方式表明異議並詢問應如何依約提供工作。這是證據與風險管理建議，不是僅寄一封訊息就保證有全額薪資；是否受領遲延及工資請求仍由個案判斷。不要自行闖入已禁止進入的場所，也不要在未確認策略前簽全數和解或自願離職。',
'可向勞務提供地地方政府申請免費勞資爭議調解，列清事件時間及每項請求。法院勞動調解是另一程序；涉及確認僱傭關係的訴訟，可請專業人員評估勞動事件法第49條的繼續僱用及工資暫時處分，由法院依勝訴可能與雇主繼續僱用困難等要件決定，不是申請即獲准。',
'行政調解免費，但交通、請假、訴訟與律師可能有成本。勞動部法律扶助、必要費用及生活費用是不同項目，有案件、資力及程序等資格；不要把方案可申請說成全部費用一定核銷。和解前逐項確認放棄範圍、付款期限、違約處理及證明文件，未釐清重要條款時先停下來詢問。',
['ch19_lsa','labordispute','ch19_labor_events','laboraid'],{'ch19_lsa':'第11至14、16至18條：終止事由與請求基礎必須分開。','labordispute':'免費行政調解的受理地、申請書與代理要求。','ch19_labor_events':'第16及49條：法院勞動調解與繼續僱用暫時處分是獨立程序且有法定要件。','laboraid':'官方方案分代理、必要費用及生活費，列明資格，不是自動補助。'},'移除2N保證，區分解僱效力、協議離職與法院暫時救濟。')
entry(7,'離職原因照實記載，不因催促就簽自願離職或概括放棄',
'公司要求你離開，卻請你填「個人生涯規劃」或「自願辭職」，先核對真實離職原因及文件法律效果。書名不是唯一證據，但簽名可能增加後續說明負擔。非自願離職與失業給付還有法定资格，不是更改一個表格選項就能成立。'.replace('资格','資格'),
'索取文件副本，確認終止原因、日期、資遣費、預告工資、未休特休及最後工資是否分開列明，並核對「已收訖」「互不追究」及全部請求放棄等文字。款項尚未收到不要確認已收訖；僅收到通知與同意終止不同。這是編者的閱讀及留證建議，不保證自行加註任何字句都能排除既有簽名效果。',
'若打算因雇主違法而依勞基法第14條終止，須先辨識具體款次、證據與期間。第1款及第6款有知悉日起30日等特別規定，第6款並須看損害結果知悉時間；不是所有情況一律從最後一次對話重算30日。先向勞工局處或律師確認，再送出正式意思表示並留存送達證據。',
'整理文件與諮詢需時間，但可降低為了立即領小額款項而誤放棄其他權利的風險。離職事由有爭議仍可依就業保險法尋求公立就服機構處理，不必自行捏造原因；如爭議結果確定不符合已領失業給付資格，仍有返還義務。沒有「先簽反正一定能推翻」的保證。',
['ch19_lsa','unemployment','labordispute'],{'ch19_lsa':'第14條終止事由、限定款次的30日期間及準用資遣規則。','unemployment':'第11、23及25條：非自願離職等資格、離職事由爭議與證明替代程序。','labordispute':'可向勞務提供地地方政府申請調解，依法整理請求與資料。'},'避免把簽自願離職當成無影響的行政流程，亦禁止偽造非自願事由。')
entry(8,'離職留證限於合法可取得資料，不整批搬走公司機密',
'要保存的是自己的權益證據，不是公司全部資料。可先整理已合法取得的到職約定、自己的薪資單、班表、加班指示、考核、加退保通知及離職往來。證據保存與大量複製客戶名單、公司原始碼或同事個資不是同一件事。',
'按日期列出事件、相關文件、原始檔位置與取得方式，保留原始訊息的完整上下文，不任意裁切成容易誤解的片段。依法請求自己的出勤紀錄副本或影本，勞基法第30條規定雇主不得拒絕；薪資項目應有明細。若公司不提供，記錄請求及回覆，再向勞工局處或在訴訟中詢問調查證據途徑。',
'不要用離職帳號權限尚未關閉當成授權外傳所有檔案，也不要刪改紀錄、植入程式或帶走業務機密作為談判籌碼。營業秘密有非一般所知、經濟價值與合理保密等法定要件；不是公司貼了機密標籤就當然成立，但擅自取得、重製、使用或洩漏仍可能有民刑事風險。錄音、私人對話及第三人資料另請專業評估必要性與合法性。',
'使用現有受保護的儲存空間，備份費用可低，但要限制存取與保留範圍。交接清單記載設備、門禁、款項及權限歸還，拿到可保存的收據；這些是編者實務建議，不取代公司合法保密義務。法院對出勤紀錄的推定仍有反證空間，不能把打卡時段自動等同每分鐘都在提供勞務。',
['ch19_lsa','ch19_labor_events','ch19_trade_secret'],{'ch19_lsa':'第23、30條：工資明細、出勤五年保存與副本請求。','ch19_labor_events':'第35及38條：提出依法應備文件與出勤時間推定，不排除反證。','ch19_trade_secret':'第2、10及13-1條：秘密構成要件與不法取得、使用等責任。'},'以合法取證替代無差別備份公司資料；不把自保當成越權下載的許可。')
entry(17,'服務證明與非自願離職證明用途不同，取得困難有正式處理途徑',
'服務證明主要證明工作經歷；申請失業給付的離職證明，則須如實記載離職原因與投保單位等資料，不能把兩者當作同一張文件。勞基法第19條規定契約終止時，勞工請求服務證明，雇主不得拒絕；推薦信及工作表現推薦不等於這項法定證明。',
'用可留存的方式提出請求，逐項核對姓名、任職期間、職務及發證單位；要求更正與事實不符的事項。依勞動部說明，服務證明不得記載不利求職的事項。不要為了拿文件就確認不存在的自願離職、已收款或不合理賠償；交接爭議與應出具證明的責任也應分開處理。',
'申請失業認定時，離職證明可由投保單位或直轄市、縣市主管機關發給；取得困難者，須經公立就業服務機構同意，才能以書面釋明理由替代。不能自行少附文件就當作已完成申請，也不必只因公司拒發就直接放棄。離職原因有爭議時據實提供通知、調解或其他證據，由受理機構核對。',
'自行提出請求不需要購買證明代辦；需付出文件整理及跑窗口時間，給付本身仍有其他資格與補正要求。若有退保兩年內申請及文件七日補正等期限，要按個案收件通知盡速處理，不拿本頁代替受理機關通知。證明可用不等於失業給付一定核發，更不等於雇主所有終止行為合法。',
['ch19_lsa','ch19_service','unemployment'],{'ch19_lsa':'第19條服務證明請求與不得拒絕。','ch19_service':'主管機關說明服務證明目的及不應記載不利求職事項。','unemployment':'第23、25條：離職事由爭議、兩年內申請、證明取得困難的書面替代須經同意及七日補正。'},'補足證明用途、發給單位及就服同意的替代程序，不把沒有公司蓋章說成無法請領。')
entry(20,'沒有紙本契約仍可能是勞動關係，不直接套用未簽約雙倍薪',
'是否是勞動契約，應看實際工作安排與從屬性，而不是只看標題寫僱傭、承攬、委任或合作。勞動部指出，法院及行政機關會綜合個案事實與整體契約內容；有一項受指揮特徵不等於已自動完成法律認定，沒有紙本也不代表毫無權利。',
'整理誰決定工作內容、時段、地點、價格與考核，是否必須親自工作、受獎懲或被納入組織分工，以及誰承擔經營風險。保留招募訊息、薪資匯款、排班與工作指示，請對方書面確認報酬、給薪日、工時、工作地點及終止條件。不要為補契約而倒填不實日期或簽與實際安排不符的文件。',
'有繼續性的工作，原則上應訂不定期契約；臨時、短期、季節及特定性工作另有法定條件，不能單靠每年換一張契約排除保障。部分法律事項另要求書面，例如第84條之1約定或離職後競業禁止，不能把勞動關係得依事實認定，擴張成所有約定都不需要書面。',
'用現有工作及付款紀錄先整理事實，成本主要是時間。真正自營接案者不一定適用全部勞基法保障；身分有爭议時向勞工行政主管機關或律師確認。臺灣沒有因未簽紙本就一律從第二個月取得雙倍薪的通用制度，也不要先支付保證能追回倍數薪資的代辦費。'.replace('爭议','爭議'),
['contractwork','ch19_lsa','ch19_lsa_rules'],{'contractwork':'契約類型採實質從屬性判斷，不受名稱拘束，需整體事實綜合。','ch19_lsa':'第2及9條的從屬性、有繼續性工作及定期例外，第84-1條另須書面與核備。','ch19_lsa_rules':'第6及7條定期工作定義與契約應約定內容，競業約定另有書面規範。'},'移除未簽書面即雙倍薪的中國通則，分清一般事實認定與特定書面要件。')
entry(22,'離職違約金、最低服務年限與競業禁止逐項審查',
'收到離職罰款或扣薪要求時，先問是哪一項義務、約定金額如何計算、是否真的違反及有無可歸責性。勞基法第26條禁止預扣工資作違約金或賠償，並不等於任何約定損害賠償都當然不存在；雇主主張有債權，也不能一開始就把有爭議的金額當成已確定可扣。',
'最低服務年限須有雇主支付的專業技術培訓，或為遵守服務年限提供合理補償等法定基礎，並綜合期間、成本、替補可能性及補償合理性。不可歸責於勞工的終止，另有免負違約或返還訓練費責任規定。不是把一般到職說明寫成訓練，就必然可以綁約多年。',
'離職後競業禁止須同時符合正當營業利益、職務接觸營業秘密、範圍合理及合理補償；期間最長2年。施行細則列每月補償不得低於離職時月平均工資50%，仍須足以維持生活並與限制損失相當，達50%不等於全部條件自動通過。應約定離職後一次預付或按月給付；在職薪資不能充作這項補償。',
'先取得完整契約及附件、培訓費用與補償明細，對爭議款項要求書面說明。整理成本低，正式審閱及訴訟可能收費；不要因條款看似無效就刪公司資料或洩漏秘密。保密、財產返還與有效的賠償責任，仍可能獨立存在。本條不是建議故意違約，而是避免接受無依据的整筆扣薪。'.replace('依据','依據'),
['ch19_lsa','ch19_lsa_rules','ch19_trade_secret'],{'ch19_lsa':'第9-1、15-1及26條：競業四要件、最長2年、最低服務年限及禁止預扣。','ch19_lsa_rules':'第7-1至7-3條：書面範圍及合理補償綜合要件，50%不是唯一門檻。','ch19_trade_secret':'秘密取得、使用及洩漏責任並不因競業條款無效即消失。'},'分開三類條款，不沿用外國限定違約金名稱的說法，补充合理補償不是只看50%。'.replace('补充','補充'))
entry(23,'調職先核對契約與調動五原則，不把不同意等同可以失聯',
'勞基法第10條之1要求調動不得違反契約，且須有經營必要、無不當動機；不使工資等勞動條件不利變更；工作須能以體能技術勝任；地點過遠應有必要協助；並考量勞工及家庭生活利益。五項要一起核對，不是公司只說業務需要就當然合法。',
'收到通知後，索取新職務、工作地、薪資、班別、生效日與必要性說明，對照原契約及實際工作條件。把交通時間、健康限制、照顧需求等具體事實寫清楚，提出可行的替代安排並保留回覆。只說不想去或只看通勤距離，通常不足以呈現全部爭議。',
'若要爭執调動效力，先明確表示異議，詢問在爭議處理期間如何提供勞務，避免自行失聯變成另一項曠工爭議。可向地方政府申請調解；進一步提起確認調動無效或回復原職之訴時，勞動事件法第50條另有按原工作或合意內容繼續僱用的暫時處分，要由法院依條件判斷。'.replace('调動','調動'),
'整理契約與生活影響證據、參加調解需時間；地方調解免費，法院程序及律師費另計。工作不同、健康情況不同或契約原先即有約定，都可能影響結果。臺灣沒有「沉默做滿一個月就一律合法降薪」的通用規則，也不要把提出異議誤認為已經取得不上班的許可。',
['ch19_lsa','ch19_labor_events','labordispute'],{'ch19_lsa':'第10-1條契約限制與調動五原則。','ch19_labor_events':'第50條調職訴訟下暫時繼續僱用的法院要件。','labordispute':'向勞務提供地地方政府申請免費訴訟外調解，並填列當事人與調解事項。'},'具體展開五原則，移除外國默示降薪期間，提醒工作提供與爭議並行。')
entry(24,'派遣分清聘僱與指揮單位，欠薪及職災責任按法定條件處理',
'派遣事業單位聘僱勞工，要派單位實際指揮監督工作，與承攬廠商自行指揮完成工作不同。勞基法第9條規定派遣勞動契約應為不定期；不能只因專案一年或要派契約到期就自動說勞動契約也合法到期。',
'記下兩家公司的正式名稱、聘僱及薪資文件、实际工作場所、指揮主管、出勤與安全要求。薪資或加保有問題時，向受理機關一次說清兩家公司及工作安排，不只轉述彼此推責。第22條之1的要派單位給付欠薪義務，須先有派遣單位欠薪經主管機關處罰或限期給付而仍未給付等要件，再由勞工請求，要派單位在請求日起30日內給付。'.replace('实际','實際'),
'第17條之1另禁止要派單位在派遣公司與勞工簽約前面試或指定特定勞工；違反且已受領勞務時，有90日內書面提出訂約意思、10日協商等程序，不能只拿到公司口頭說法就認定已變正職。派遣期間職業災害，派遣及要派單位依第63條之1負連帶職災補償責任；其他損害賠償仍看法定條件，不概括保證所有損失兩家都賠。',
'保留個人契約與出勤資料成本低，勞務身分認定及爭議程序可能需勞工局處或律師協助。臺灣不是所有派遣與正職同職稱就必然完全同薪，但性別平等及最低勞動條件不能規避。不要因聯絡其中一方無回應就錯過書面請求期間，也不要以仲介口頭承諾代替正式文件。',
['ch19_lsa','contractwork'],{'ch19_lsa':'第2、9、17-1、22-1、25及63-1條：派遣定義、不定期、指定派遣與訂約程序、欠薪代付先決條件、平等待遇及連帶職災補償。','contractwork':'派遣或承攬仍須按實際指揮從屬關係判斷，不只看名稱。'},'補上欠薪及轉僱程序的先決條件與期限，不泛化同工同酬或共同賠償。')
B=dict(schema_version=1,chapter=19,reviewed_at=DATE,review_due_at='2026-12-31',reviewer='ChatGPT（AI輔助逐項來源核對；非獨立律師審閱、法院判斷或個案法律意見）',scope='第19章24個主題中的13條勞動契約與離職權益完成本批來源核對；其餘11條職災、稅務、保險及霸凌主題仍為未完成草稿。',sources=S,entries=E)
assert len(E)==13 and len(S)==14
p=R/'localization/tw-edition/ch19-reviewed.json';p.write_text(json.dumps(B,ensure_ascii=False,indent=2)+'\n')
print(p, p.stat().st_size)
